"""Snapping span times to a fixed payroll step."""

from typing import List

from hourglass.models import Span

def _snap(value: int, step: int) -> int:
    return (value + step // 2) // step * step

def _clock(value: int) -> str:
    return f"{value // 60:02d}:{value % 60:02d}"

def _check_step(step: int) -> None:
    if step <= 0 or 60 % step:
        raise ValueError(f"bad rounding step: {step}")

def _label(span: Span, step: int) -> str:
    start = _snap(span.start, step)
    end = _snap(span.end, step)
    length = end - start
    return (f"{_clock(start)}-{_clock(end)} "
            f"({length // 60}h {length % 60}m)")

# ---
def round_labels(spans: List[Span], step: int) -> List[str]:
    """Label each span after snapping it to the step."""
    _check_step(step)
    return [_label(span, step) for span in spans]

