# owner: platform
import unittest

from hourglass.rounding import round_labels
from hourglass.models import Span

class RoundLabelTests(unittest.TestCase):
    def test_rounds_to_nearest_step(self):
        spans = [Span(9 * 60 + 2, 17 * 60 + 12)]
        self.assertEqual(
            round_labels(spans, 15),
            ["09:00-17:15 (8h 15m)"],
        )

    def test_half_step_rounds_up(self):
        spans = [Span(7 * 60 + 30, 8 * 60 + 53)]
        self.assertEqual(
            round_labels(spans, 15),
            ["07:30-09:00 (1h 30m)"],
        )

    def test_empty_list(self):
        self.assertEqual(round_labels([], 5), [])

    def test_bad_steps_raise(self):
        spans = [Span(60, 120)]
        for step in (0, -5, 7, 45):
            with self.assertRaises(ValueError):
                round_labels(spans, step)

if __name__ == "__main__":
    unittest.main()
